/**
 * Event Bus - In-memory pub/sub for inter-service communication
 * No direct service-to-service calls allowed. All communication goes through this bus.
 */

type EventCallback = (payload: any) => void;

class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in subscriber for event '${event}':`, error);
        }
      });
    }
  }
}

export const eventBus = new EventBus();

/**
 * User Service
 * Manages user data. No other service may access this store.
 */

interface User {
  id: string;
  name: string;
  email: string;
}

class UserService {
  private store: Map<string, User> = new Map();
  private nextId = 1;

  /**
   * Create a new user
   */
  create(name: string, email: string): User {
    const id = `user-${this.nextId++}`;
    const user: User = { id, name, email };
    this.store.set(id, user);
    return user;
  }

  /**
   * Get user by ID
   */
  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  /**
   * Get all users
   */
  listAll(): User[] {
    return Array.from(this.store.values());
  }

  /**
   * Update user
   */
  update(id: string, updates: Partial<Omit<User, 'id'>>): User | undefined {
    const user = this.store.get(id);
    if (!user) return undefined;

    const updated: User = {
      ...user,
      ...updates,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete user
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service
 * Manages project data and memberships. No other service may access this store.
 */

interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

class ProjectService {
  private store: Map<string, Project> = new Map();
  private nextId = 1;

  /**
   * Create a new project
   */
  create(name: string, description: string): Project {
    const id = `project-${this.nextId++}`;
    const project: Project = {
      id,
      name,
      description,
      memberIds: [],
    };
    this.store.set(id, project);
    return project;
  }

  /**
   * Get project by ID
   */
  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  /**
   * Get all projects
   */
  listAll(): Project[] {
    return Array.from(this.store.values());
  }

  /**
   * Update project
   */
  update(
    id: string,
    updates: Partial<Omit<Project, 'id' | 'memberIds'>>
  ): Project | undefined {
    const project = this.store.get(id);
    if (!project) return undefined;

    const updated: Project = {
      ...project,
      ...updates,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete project
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Add member to project
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove member from project
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    project.memberIds = project.memberIds.filter(id => id !== userId);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service
 * Manages task data. Publishes events to the event bus for status changes and assignments.
 * No other service may access this store.
 */

import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

class TaskService {
  private store: Map<string, Task> = new Map();
  private nextId = 1;

  /**
   * Create a new task
   */
  create(title: string, description: string, projectId: string): Task {
    const id = `task-${this.nextId++}`;
    const task: Task = {
      id,
      title,
      description,
      status: 'todo',
      assigneeId: null,
      projectId,
    };
    this.store.set(id, task);
    return task;
  }

  /**
   * Get task by ID
   */
  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  /**
   * Get all tasks for a project
   */
  listByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      task => task.projectId === projectId
    );
  }

  /**
   * Get all tasks
   */
  listAll(): Task[] {
    return Array.from(this.store.values());
  }

  /**
   * Update task (title and description only)
   */
  update(
    id: string,
    updates: Partial<Pick<Task, 'title' | 'description'>>
  ): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated: Task = {
      ...task,
      ...updates,
    };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete task
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Change task status (forward-only transitions)
   * Transitions: todo -> in-progress -> done
   */
  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const validTransitions: Record<TaskStatus, TaskStatus[]> = {
      'todo': ['in-progress'],
      'in-progress': ['done'],
      'done': [],
    };

    if (!validTransitions[task.status].includes(newStatus)) {
      return undefined; // Invalid transition
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(id, task);

    // Publish event for status change
    eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }

  /**
   * Assign task to user
   */
  assign(id: string, assigneeId: string): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    task.assigneeId = assigneeId;
    this.store.set(id, task);

    // Publish event for task assignment
    eventBus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    });

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service
 * Manages comment data. Publishes events to the event bus when comments are added.
 * No other service may access this store.
 */

import { eventBus } from '../event-bus';

interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

class CommentService {
  private store: Map<string, Comment> = new Map();
  private nextId = 1;

  /**
   * Create a new comment
   */
  create(
    taskId: string,
    authorId: string,
    body: string,
    taskTitle?: string,
    authorName?: string
  ): Comment {
    const id = `comment-${this.nextId++}`;
    const createdAt = new Date().toISOString();
    const comment: Comment = {
      id,
      taskId,
      authorId,
      body,
      createdAt,
    };
    this.store.set(id, comment);

    // Publish event for comment added
    eventBus.publish('comment.added', {
      commentId: id,
      taskId,
      taskTitle: taskTitle || '',
      authorId,
      authorName: authorName || '',
    });

    return comment;
  }

  /**
   * Get comment by ID
   */
  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  /**
   * Get all comments for a task
   */
  listByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      comment => comment.taskId === taskId
    );
  }

  /**
   * Get all comments
   */
  listAll(): Comment[] {
    return Array.from(this.store.values());
  }

  /**
   * Delete comment
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

